    /// <summary>
    /// MPJ_2864 - kscerri - 16/03/2021
    /// Parameter to include number of tasks.
    /// </summary>
    /// <param name = "_numOfTasks">NumOfThreads</param>
    /// <returns>NumOfThreads</returns>
    [
        DataMemberAttribute, 
        SysOperationLabelAttribute('@MET:CustCreditLimitTasks'),
        SysOperationDisplayOrderAttribute('1')
    ]
    public METNumOfTasks getNumOfTasks(METNumOfTasks _numOfTasks = numOfTasks)
    {
        numOfTasks = _numOfTasks;
        return numOfTasks;
    }

/// <summary>
/// MPJ_2864 - kscerri - 22/03/2021
/// </summary>
/// <param name = "_custAccounts">customer account list</param>
/// <returns>list of customer accounts</returns>
[
    DataMemberAttribute, 
    AifCollectionTypeAttribute(identifierStr(_CustAccounts), Types::String),
    SysOperationLabelAttribute('@MET:CustCreditLimitCustAccounts')
]
public List getCustAccountList(List _custAccounts = custAccounts)
{
    custAccounts = _custAccounts;
    return custAccounts;
}
